使用示例： //创建HTTP客户端
http_clientclient;

//GET请求
autoresponse=client.get("https://api.example.com/users");
if(response.is_success()){
println(response.body);
}

//POSTJSON请求
stringjson=R"({"name":"John","age":30})";
autopost_resp=client.post_json("https://api.example.com/users",json);

//POST表单请求
unordered_map<string,string>form={{"username","john"},{"password","123"}};
autoform_resp=client.post_form("https://example.com/login",form);

//设置自定义请求头
unordered_map<string,string>headers={{"Authorization","Bearertoken123"}};
autoauth_resp=client.get("https://api.example.com/profile",headers);

//下载文件
client.download_file("https://example.com/file.zip","/path/to/save/file.zip");

//设置代理
client.set_proxy("proxy.example.com",8080);

//设置超时
client.set_timeout(milliseconds(5000));

//异步请求
autofuture=client.request_async(req);
autoasync_resp=future.get();
